changeSet.sql:
CREATE TABLE vaultnote.refresh_tokens ( id BIGINT GENERATED BY DEFAULT AS IDENTITY, user_id BIGINT NOT NULL, token_hash VARCHAR(64) NOT NULL, token_family_id UUID NOT NULL, expires_at TIMESTAMP WITH TIME ZONE NOT NULL, revoked_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_refresh_tokens PRIMARY KEY (id), CONSTRAINT uk_refresh_tokens_hash UNIQUE (token_hash), CONSTRAINT fk_refresh_tokens_user FOREIGN KEY (user_id) REFERENCES vaultnote.users (id) ON DELETE CASCADE, CONSTRAINT ck_refresh_tokens_expiry CHECK (expires_at > created_at), CONSTRAINT ck_refresh_tokens_revoked_at CHECK (revoked_at IS NULL OR revoked_at >= created_at) );
CREATE INDEX ix_refresh_tokens_user_id ON vaultnote.refresh_tokens (user_id);
CREATE INDEX ix_refresh_tokens_family_id ON vaultnote.refresh_tokens (token_family_id);
